// SCRUM-905 staging proof harness (the BEO's kitchen and bar plan pick from the till's menu), as run on 12 November
// 2026 against oto-app-staging dep-dbqpg45bedkc73ec1fbg and oto-api-staging dep-dbqpg3tckfvc73d4ioog (both 4392efbfe;
// the api moved to d0045f1ef, which contains it, at 10:54Z). One file: every script of the run as text;
// `node proof.mjs <folder>` writes them out. The driver keeps one headless Chromium open and runs a step per request
// (node go.mjs <step> "<arg>"); credentials by NAME only through scripts/agent/env.mjs need(); staff names held in
// memory for masking only. The run, in order (UTC):
//   deploys.mjs deploys.json before (10:48) | app-in (10:49) | pos-menu (10:49) | create-event (10:50) |
//   act reload, open accordion-kitchen-plan, click button-add-first-menu-kids | pick button-till-menu-kids-0|pizza|CF-24|01-p1-kids-line |
//   act click button-add-menu-extra-kids | pick button-till-menu-kids-1|pepperoni|CF-31 | act click button-add-menu-extra-kids |
//   act type input-menu-name-kids-2|ZZ TEST fish fingers | pic 02-... | act tab adults | pic 03a-... | act click switch-adults-differ |
//   act click button-add-menu-extra-adults | pick button-till-menu-adults-3|schnitzel|CF-37|03b-p3-adults-extra | pic 03c-... |
//   act open accordion-bar-plan | act click button-add-bar-extra | pick button-till-menu-bar-0|juice|CF-63-2|04-p3-bar |
//   save first (10:53) | act reload ... | pic 05-... | pick kids-0 "not from the till" (no pick) 06 | pick bar-0 "pizza" (no pick) 07 |
//   till-read before-package | package (10:54) | till-read after-package | parent-link (10:55) | act reload | rows |
//   act click button-add-set-menu-item | pick button-till-menu-kids-11|hummus|CF-13 | picbox 08-... | save second |
//   till-read after-set-menu | pdf (picture 09 rendered locally with PyMuPDF) | settings list | settings dialog (10:59) |
//   pick kids-10 "fries" (no pick) 12 | dead-code (11:00) | pic 13-... | till-read dead-code | clear button-till-menu-kids-11 |
//   save after-clear | role MANAGER | role RECEPTION (11:02) | timing | cleanup (11:02:44) | GET /STOP (signs every session
//   out, closes the browser) | deploys.mjs deploys.json after | receipt.mjs | namecheck.mjs receipt.json.
// Pictures removed after the run as duplicates of others: the unfiltered lists of 03b, 06, 07 and 12, and 15 (the
// reception account showed the same screen as picture 14). dbg.mjs, dbg2.mjs and look.mjs were operator aids.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const FILES = {
 "driver.mjs": "// SCRUM-905 staging proof driver (the BEO's kitchen and bar plan pick from the till's menu): one headless Chromium\n// kept open, steps run on request (GET http://127.0.0.1:47905/<step>.mjs?arg). Credentials by NAME only through\n// scripts/agent/env.mjs need(); never prints a phone, a password, a token, a setting's value or a person's name.\nimport assert from 'node:assert/strict';\nimport { createServer } from 'node:http';\nimport { createRequire } from 'node:module';\nimport { randomUUID } from 'node:crypto';\nimport { mkdirSync, writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { pathToFileURL } from 'node:url';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\n\nconst REPO = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p905/';\nconst STEPS = HERE + 'steps/';\nconst REL = 'docs/qa/proof-2026-11-12/SCRUM-905';\nconst OUT = REPO + '/' + REL;\nmkdirSync(OUT, { recursive: true });\nmkdirSync(HERE + 'raw', { recursive: true });\nconst { chromium, request } = createRequire(REPO + '/apps/pos/package.json')('@playwright/test');\n\nconst SHA = '4392efbfe44368a3f32cb9c1b68fc6c43986efc4';\nconst POS = 'https://oto-pos-web-staging.onrender.com';\nconst LAUNCHER = 'https://oto-launcher-staging.onrender.com';\nconst APP = 'https://oto-app-staging.onrender.com';\n\nconst workFile = HERE + 'work.json';\nconst st = existsSync(workFile)\n  ? JSON.parse(readFileSync(workFile, 'utf8'))\n  : { unit: 'SCRUM-905 staging proof', liveCommit: SHA, startedAt: new Date().toISOString(), images: [], log: [], points: {}, pageErrors: [] };\nconst save = () => writeFileSync(workFile, JSON.stringify(st, null, 2) + '\\n');\nsave();\n\n// Names to mask, held in memory only (never written, never printed).\nconst NAMES = new Set();\nconst addNames = (...vals) => {\n  for (const v of vals) {\n    if (typeof v !== 'string') continue;\n    const t = v.trim();\n    if (t.length < 2 || /^ZZ TEST/i.test(t)) continue;\n    NAMES.add(t);\n  }\n};\n\nconst browser = await chromium.launch({ headless: true });\nst.browser = 'Chromium ' + browser.version(); save();\nconst newContext = (viewport = { width: 1440, height: 1000 }) =>\n  browser.newContext({ viewport, timezoneId: 'Asia/Bangkok', locale: 'en-GB', colorScheme: 'light' });\n\n/** One request through a context's cookie jar (browser context or API context); status and body. */\nconst call = async (ctx, origin, method, path, body) => {\n  const headers = method === 'GET' ? {} : { 'Idempotency-Key': randomUUID() };\n  const r = await (ctx.request ?? ctx).fetch(origin + '/api' + path, { method, data: body, headers, timeout: 120000 });\n  const text = await r.text();\n  let b = null;\n  try { b = JSON.parse(text); } catch { b = text.slice(0, 300); }\n  return { status: r.status(), body: b };\n};\n\nconst launcherSignIn = async (ctx, phoneKey = 'STAGING_ADMIN_PHONE', passKey = 'STAGING_ADMIN_PASSWORD') => {\n  const s = await call(ctx, LAUNCHER, 'POST', '/auth/sign-in', { phone: need(phoneKey), password: need(passKey) });\n  return s.status;\n};\nconst handTo = async (ctx, app) => {\n  const h = await call(ctx, LAUNCHER, 'POST', '/auth/handoff', { app });\n  if (h.status !== 200) return { status: h.status, code: h.body?.error?.code ?? null, message: h.body?.error?.message ?? null };\n  const page = await ctx.newPage();\n  const want = '/api/auth/handoff';\n  const exchange = page.waitForResponse((r) => new URL(r.url()).pathname === want && r.request().method() === 'POST', { timeout: 90000 });\n  await page.goto(h.body.launchUrl);\n  const response = await exchange;\n  const status = response.status();\n  await response.finished().catch(() => {});\n  await page.waitForURL((u) => !u.hash.includes('handoff'), { timeout: 60000 }).catch(() => {});\n  return { status: 200, exchange: status, page };\n};\n\n/** Redact the names: text nodes, input values, placeholders and titles. Returns how many runs were masked. */\nconst redact = async (page) =>\n  page.evaluate((strings) => {\n    const needles = [...new Set(strings)].sort((a, b) => b.length - a.length);\n    if (!needles.length) return 0;\n    const esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    const re = new RegExp(needles.map((s) => '(?<![A-Za-z])' + esc(s) + '(?![A-Za-z])').join('|'), 'gi');\n    let n = 0;\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    const hits = [];\n    while (walker.nextNode()) {\n      const t = walker.currentNode;\n      if (t.parentElement?.closest('[data-redacted]')) continue;\n      re.lastIndex = 0;\n      if (re.test(t.nodeValue || '')) hits.push(t);\n    }\n    for (const t of hits) {\n      let html = (t.nodeValue || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n      re.lastIndex = 0;\n      html = html.replace(re, (m) => { n += 1; return `<span data-redacted=\"1\" style=\"background:#3f3f46;color:#3f3f46;border-radius:3px\">${m.replace(/./g, '█')}</span>`; });\n      const span = document.createElement('span');\n      span.setAttribute('data-redacted', 'wrap');\n      span.innerHTML = html;\n      t.parentNode.replaceChild(span, t);\n    }\n    for (const el of document.querySelectorAll('input, textarea')) {\n      re.lastIndex = 0;\n      if (re.test(el.value || '')) { el.style.color = '#3f3f46'; el.style.background = '#3f3f46'; n += 1; }\n      re.lastIndex = 0;\n      if (el.placeholder && re.test(el.placeholder)) { re.lastIndex = 0; el.placeholder = el.placeholder.replace(re, (m) => '█'.repeat(m.length)); n += 1; }\n    }\n    for (const el of document.querySelectorAll('[title]')) {\n      re.lastIndex = 0;\n      if (re.test(el.getAttribute('title') || '')) { re.lastIndex = 0; el.setAttribute('title', el.getAttribute('title').replace(re, '█')); }\n    }\n    return n;\n  }, [...NAMES]);\n\n/** After a redaction: how many names are still readable in the visible text or in a field. */\nconst leaks = async (page) =>\n  page.evaluate((strings) => {\n    const vis = (el) => { const s = getComputedStyle(el); return s.visibility !== 'hidden' && s.display !== 'none'; };\n    const parts = [];\n    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    while (walker.nextNode()) {\n      const el = walker.currentNode.parentElement;\n      if (!el || el.closest('[data-redacted]') || el.closest('[data-board-hidden]') || !vis(el)) continue;\n      parts.push(walker.currentNode.nodeValue || '');\n    }\n    const text = ' ' + parts.join(' ') + ' ';\n    const fields = [...document.querySelectorAll('input, textarea')].filter((e) => !e.closest('[data-board-hidden]')).map((e) => ((e.style.color === 'rgb(63, 63, 70)' ? '' : e.value) + ' ' + (e.placeholder || ''))).join(' ');\n    const esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    return strings.filter((s) => { const re = new RegExp('(?<![A-Za-z])' + esc(s) + '(?![A-Za-z])', 'i'); return re.test(text) || re.test(fields); }).length;\n  }, [...NAMES]);\n\n/** A picture: names redacted, the leak check passed, optional masks, clip or element. */\nconst shot = async (page, name, opts = {}) => {\n  await page.waitForTimeout(opts.settle ?? 700);\n  const masked = await redact(page);\n  const left = await leaks(page);\n  if (left !== 0) throw new Error('a name is still readable; picture not taken: ' + name);\n  const file = OUT + '/' + name;\n  const o = { path: file, mask: opts.mask ?? [], maskColor: '#3f3f46', fullPage: !!opts.fullPage, ...(opts.clip ? { clip: opts.clip } : {}) };\n  if (opts.element) await opts.element.screenshot({ path: file, mask: o.mask, maskColor: o.maskColor });\n  else await page.screenshot(o);\n  st.images = st.images.filter((i) => i.file !== name);\n  st.images.push({ file: name, at: new Date().toISOString(), shows: opts.shows ?? null, namesMasked: masked, masks: (opts.mask ?? []).length });\n  save();\n  return name;\n};\n\nconst one = (s) => String(s ?? '').replace(/\\s+/g, ' ').trim();\n/** Names out of a string, for anything kept. */\nconst scrub = (s) => {\n  if (typeof s !== 'string') return s;\n  let t = s;\n  for (const n of [...NAMES].sort((a, b) => b.length - a.length)) t = t.replace(new RegExp('(?<![A-Za-z])' + n.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '(?![A-Za-z])', 'gi'), '█');\n  return t.replace(/\\+?\\d[\\d\\s().-]{6,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 ? '[number]' : m));\n};\n\n/** Page errors, failed api calls (status >= 400) and console errors of a page, kept scrubbed. */\nconst watch = (page, label) => {\n  page.on('pageerror', (e) => { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'pageerror', text: scrub(String(e.message).split('\\n')[0].slice(0, 240)) }); save(); });\n  page.on('console', (m) => { if (m.type() === 'error') { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'console.error', text: scrub(m.text().split('\\n')[0].slice(0, 240)) }); save(); } });\n  page.on('response', (r) => { try { const u = new URL(r.url()); if (r.status() >= 400 && /\\/api\\//.test(u.pathname)) { st.pageErrors.push({ page: label, at: new Date().toISOString(), kind: 'http', text: `${r.request().method()} ${u.pathname.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/g, ':id')} ${r.status()}` }); save(); } } catch {} });\n};\n\nconst ctxs = {};\nconst S = { need, st, save, browser, ctxs, newContext, request, call, launcherSignIn, handTo, redact, leaks, shot, addNames, NAMES, SHA, POS, LAUNCHER, APP, OUT, REL, HERE, randomUUID, assert, one, scrub, watch };\n\nconst server = createServer(async (req, res) => {\n  const u = new URL(req.url ?? '/', 'http://x');\n  const file = decodeURIComponent(u.pathname.slice(1));\n  const arg = u.search ? decodeURIComponent(u.search.slice(1)) : '';\n  let out;\n  try {\n    if (file === 'STOP') {\n      const mod = await import(pathToFileURL(STEPS + 'signout.mjs').href + '?t=' + Date.now());\n      out = await mod.default(S, arg).catch((e) => ({ error: String(e?.message ?? e).slice(0, 500) }));\n      save();\n      res.setHeader('content-type', 'application/json');\n      res.end(JSON.stringify(out, null, 2));\n      await browser.close();\n      server.close();\n      process.exit(0);\n    }\n    const mod = await import(pathToFileURL(STEPS + file).href + '?t=' + Date.now());\n    out = { ok: true, result: await mod.default(S, arg) };\n  } catch (e) {\n    out = { ok: false, error: scrub(String(e?.stack ?? e)).slice(0, 3000) };\n  }\n  st.log.push({ at: new Date().toISOString(), step: file, arg, ok: out.ok });\n  save();\n  res.setHeader('content-type', 'application/json');\n  res.end(JSON.stringify(out, null, 2));\n});\nserver.listen(47905, '127.0.0.1', () => console.log('driver ready on 47905'));\n",
 "go.mjs": "// Call one driver step with an encoded argument: node go.mjs <step> <arg>\nconst [step, arg = ''] = process.argv.slice(2);\nconst r = await fetch('http://127.0.0.1:47905/' + step + '.mjs' + (arg ? '?' + encodeURIComponent(arg) : ''), { signal: AbortSignal.timeout(290000) });\nconst j = await r.json();\nconsole.log(JSON.stringify(j, null, 1).slice(0, 9000));\n",
 "deploys.mjs": "// READ-ONLY. The two named *-staging deploys of SCRUM-905 by id, and what each serves now. Never prints the key.\n// node deploys.mjs <out.json> [tag]\nimport { writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\nconst headers = { authorization: `Bearer ${need('RENDER_API_KEY')}`, accept: 'application/json' };\nconst get = async (path) => { const r = await fetch('https://api.render.com/v1' + path, { headers, signal: AbortSignal.timeout(60000) }); return r.ok ? r.json() : { _status: r.status }; };\nconst want = { 'oto-api-staging': 'dep-dbqpg3tckfvc73d4ioog', 'oto-app-staging': 'dep-dbqpg45bedkc73ec1fbg' };\nconst services = (await get('/services?limit=50')).map((r) => r.service ?? r).filter((s) => /-staging$/.test(s.name));\nconst out = process.argv[2];\nconst tag = process.argv[3] ?? 'read';\nconst state = existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')) : {};\nconst snap = { readAt: new Date().toISOString(), services: {} };\nfor (const [name, dep] of Object.entries(want)) {\n  const s = services.find((x) => x.name === name);\n  if (!s) { snap.services[name] = null; continue; }\n  const d = await get(`/services/${s.id}/deploys/${dep}`);\n  const list = (await get(`/services/${s.id}/deploys?limit=5`)).map((x) => x.deploy ?? x);\n  const live = list.find((x) => x.status === 'live');\n  snap.services[name] = {\n    named: { id: d.id, status: d.status, sha: d.commit?.id, createdAt: d.createdAt, finishedAt: d.finishedAt, trigger: d.trigger ?? null },\n    live: live ? { id: live.id, sha: live.commit?.id, createdAt: live.createdAt, finishedAt: live.finishedAt } : null,\n    latest: list[0] ? { id: list[0].id, status: list[0].status, sha: list[0].commit?.id } : null,\n  };\n}\nstate[tag] = snap;\nwriteFileSync(out, JSON.stringify(state, null, 2) + '\\n');\nconsole.log(JSON.stringify(snap, null, 1));\n",
 "receipt.mjs": "// Builds docs/qa/proof-2026-11-12/SCRUM-905/receipt.json from the driver's work file: routes, statuses, ids, codes\n// and menu item names, scrubbed (no staff name, no phone, no cookie, no key, no parent-link token). node receipt.mjs\nimport { readFileSync, writeFileSync, readdirSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p905/';\nconst DIR = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-905/';\nconst st = JSON.parse(readFileSync(HERE + 'work.json', 'utf8'));\nconst pics = readdirSync(DIR).filter((f) => f.endsWith('.png')).sort();\nconst pick = (k) => (st.picks[k] ?? []).map((p) => ({ at: p.at, button: p.tid, openMs: p.openMs, listed: p.unfilteredCount, firstGroups: p.firstGroups?.map((g) => `${g.heading} (${g.items})`), search: p.search ?? null, found: p.filtered?.options?.map((o) => o.text.replace(/(CF-|PARTY-|RC-)/, ' $1').replace(/฿/, ' ฿')) ?? null, picked: p.pickedText ?? null, closedAfterPick: p.closedAfterPick ?? null }));\nconst line = (l) => `${l.itemName} | code ${l.productCode ?? '-'} | price ${l.price} | included ${l.included} | source ${l.source ?? '-'}${l.groupId ? ' | template group ' + l.groupId : ''}`;\nconst read = (r) => r && { route: r.route, status: r.status, setMenuEnabled: r.kitchen?.setMenuEnabled, adultsDiffer: r.kitchen?.adultsDiffer, kids: r.kitchen?.kids?.map(line), adults: r.kitchen?.adults?.map(line), bar: r.bar?.items?.map(line) };\nconst till = (t) => t && { at: t.at, route: t.route, status: t.status, planStatus: t.planStatus, package: t.package, kitchenLines: t.setMenu?.map((m) => `${m.productCode ?? '(no code)'} ${m.name}${m.chosenOption ? ' -> ' + m.chosenOption : ''}${m.audience ? ' [' + m.audience + ' only]' : ''}`) ?? null, barLines: t.barItems?.map((b) => `${b.productCode ?? '(no code)'} ${b.name} x${b.qty}`) ?? null, slips: t.slips };\nconst images = pics.map((f) => {\n  const i = st.images.find((x) => x.file === f);\n  if (f.startsWith('09-')) return { file: f, shows: 'The ZZ TEST BEO PDF (GET /api/events/:id/beo/pdf, page 1, rendered locally): kitchen plan with EXTRA 400/420/425 baht and the bar line; its text was checked: no staff name', namesMasked: 0 };\n  if (f.startsWith('14-')) return { file: f, shows: 'The staging manager account through the launcher: the OTO App hand-off refused (403); the app shows \"Open the OTO App from the OTO launcher\" (the reception account showed the same)', namesMasked: 0 };\n  return i ? { file: f, at: i.at, shows: i.shows, namesMasked: i.namesMasked, masks: i.masks } : { file: f };\n});\nconst receipt = {\n  unit: 'SCRUM-905 staging proof',\n  ticket: 'SCRUM-905',\n  title: \"BEO kitchen and bar plan: pick from the till's menu\",\n  landed: '4392efbfe44368a3f32cb9c1b68fc6c43986efc4 (six commits, 416567c7e..4392efbfe)',\n  deploys: {\n    file: 'deploys.json (before: both named deploys live at 4392efbfe; after: read at the end)',\n    api: 'dep-dbqpg3tckfvc73d4ioog live 10:47:25Z at 4392efbfe; replaced at 10:54:24Z by dep-dbqpjllbedkc73ecb2rg at d0045f1ef, which contains 4392efbfe (15 later commits: messaging, inbox and Twilio test line; none touches the party menu door, the menu read, the party plan, the parties route or the OTO App). The till-menu comparison (10:49Z) ran on 4392efbfe; the till party reads (10:54:29Z on) ran on d0045f1ef.',\n    app: 'dep-dbqpg45bedkc73ec1fbg live 10:45:26Z at 4392efbfe, still live at the end.',\n  },\n  startedAt: st.startedAt,\n  finishedAt: st.signOut?.at ?? null,\n  browser: 'Headless ' + st.browser + ' (Playwright), one browser for the whole run, closed at the end',\n  rules: 'ZZ TEST records only (one party, deleted and read back gone); no real party, BEO or template opened for editing; no POS product created; nothing printed (party on 25 Nov, park names no party slips station); no payment; no direct database access; staff names held in memory for masking only; the signed-in initials masked',\n  viewer: { role: st.app.role, park: st.app.centralFlorestaName.trim(), linkedTillBranch: st.posMenu.platformBranch.name },\n  tillMenuComparison: {\n    door: st.app.tillMenuDoor,\n    till: { routes: st.posMenu.routes, productsAtBranch: st.posMenu.products, expectedForPicker: `${st.posMenu.expected} (kind menu, active, not archived, coded, made at the kitchen or the bar; BEO-only included)`, tillSellingGridMenuItems: st.posMenu.tillSellingGridMenuItems },\n    door_vs_till: { door: st.posMenu.door, till: st.posMenu.expected, missingFromPicker: st.posMenu.missingFromDoor, extraInPicker: st.posMenu.extraInDoor, fieldMismatches: st.posMenu.mismatched, duplicateCodes: st.posMenu.duplicateCodes },\n    byStation: st.posMenu.doorByStation,\n    uncodedKitchenBarItemsOnSale: st.posMenu.uncodedKitchenBarItemsOnSale.length,\n    menuItemsPrintingNowhereOnSale: st.posMenu.menuItemsPrintingNowhereOnSale.length,\n    offSaleCodedItems: st.posMenu.offSaleCodedItems.length,\n    sample: st.posMenu.sample,\n    partyOnlyItemsListed: st.tillMenuItems.filter((i) => i.beoOnly).map((i) => `${i.code} ${i.name}`),\n    weekendPriceDiffers: st.tillMenuItems.filter((i) => i.priceWeekendSatang !== i.priceSatang).length,\n    timing: st.timing,\n  },\n  party: { ...st.event, packageApplied: st.packageApplied, parentLink: st.parentLink },\n  picks: { kidsLine0: pick('kids0'), kidsExtra: pick('kids1'), adultsExtra: pick('adults3'), bar: pick('bar0'), reopenCodedLine: pick('kids0-reopen'), barSearchPizza: pick('bar0-pizza'), setMenuAddItem: pick('kids11-setmenu-add'), fries: pick('kids10-fries') },\n  saves: Object.fromEntries(Object.entries(st.saves).map(([k, s]) => [k, { at: s.at, putStatus: s.putStatus, ms: s.ms, writes: s.writes, toasts: s.toasts, readBack: read(s.read) }])),\n  tillReads: Object.fromEntries(Object.entries(st.tillReads).map(([k, t]) => [k, till(t)])),\n  pdf: { ...st.pdf, note: 'kept in the scratch folder only; page 1 rendered as picture 09; its text was searched for every held staff name: none' },\n  deadCode: st.deadCode,\n  settings: {\n    templatesAtStart: st.settings.before.map((t) => `${t.name}${t.isActive === false ? ' (inactive)' : ''}`),\n    deadCodesInRealTemplates: st.settings.deadCodesExpected,\n    marksShownInList: st.settings.marksOnScreen,\n    newTemplateDialog: { title: st.settings.dialogTitle, searchBesideCode: st.settings.searchBeside, deadMarkForZZDEAD1: st.settings.deadMark, searchFries: st.settings.searchFries, afterPick: st.settings.afterPick, choiceOptionAfterPick: st.settings.optionAfterPick, closedWithCancel: st.settings.dialogClosed },\n    templatesUnchanged: st.settings.unchanged,\n  },\n  roles: {\n    admin: { role: st.app.role, sees: 'the search beside every kitchen, adults, set-menu \"+ Add item\" and bar line (pictures 01-08)' },\n    ...Object.fromEntries(Object.entries(st.roles).map(([k, r]) => [k, { launcherSignIn: r.launcherSignIn, appHandoffExchange: r.handoff?.exchange ?? null, appUser: r.appUser, tillMenuDoor: r.tillMenuDoor?.status, landedPath: r.landedPath, screenSays: r.screenSays ?? null, signOut: r.signOut, picture: k === 'manager' ? '14-p8-staging-manager-account-has-no-oto-app-login.png' : null }])),\n  },\n  pageErrors: st.pageErrors,\n  cleanup: st.cleanup,\n  signOut: st.signOut,\n  images,\n};\nlet text = JSON.stringify(receipt, null, 2);\ntext = text.replace(/\\+?\\d[\\d\\s().-]{7,}\\d/g, (m) => ((m.match(/\\d/g) || []).length >= 9 && !/^\\d{4}-\\d{2}/.test(m) ? '[number]' : m));\nwriteFileSync(DIR + 'receipt.json', text + '\\n');\nconsole.log('written', text.length, 'images', images.length);\n",
 "namecheck.mjs": "// Counts held staff names in a file (never prints them). node namecheck.mjs <file>\nimport { readFileSync } from 'node:fs';\nconst t = readFileSync(process.argv[2], 'utf8');\nconst names = readFileSync('C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p905/raw/names.txt', 'utf8').split('\\n').filter((n) => n.trim().length >= 3);\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nconst hits = names.filter((n) => new RegExp('(?<![A-Za-z])' + esc(n.trim()) + '(?![A-Za-z])', 'i').test(t));\nconsole.log('name hits:', hits.length, 'lengths:', hits.map((h) => h.length).join(','));\nconsole.log('token-like:', /[0-9a-f]{48}/.test(t));\n",
 "bundle.mjs": "// Writes docs/qa/proof-2026-11-12/SCRUM-905/proof.mjs: every script of the run as text, and `node proof.mjs <folder>`\n// writes them back out. node bundle.mjs\nimport { readFileSync, readdirSync, writeFileSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p905/';\nconst OUT = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-905/proof.mjs';\nconst files = {};\nfor (const f of ['driver.mjs', 'go.mjs', 'deploys.mjs', 'receipt.mjs', 'namecheck.mjs', 'bundle.mjs']) files[f] = readFileSync(HERE + f, 'utf8');\nfor (const f of readdirSync(HERE + 'steps').filter((x) => x.endsWith('.mjs')).sort()) files['steps/' + f] = readFileSync(HERE + 'steps/' + f, 'utf8');\nconst head = `// SCRUM-905 staging proof harness (the BEO's kitchen and bar plan pick from the till's menu), as run on 12 November\n// 2026 against oto-app-staging dep-dbqpg45bedkc73ec1fbg and oto-api-staging dep-dbqpg3tckfvc73d4ioog (both 4392efbfe;\n// the api moved to d0045f1ef, which contains it, at 10:54Z). One file: every script of the run as text;\n// \\`node proof.mjs <folder>\\` writes them out. The driver keeps one headless Chromium open and runs a step per request\n// (node go.mjs <step> \"<arg>\"); credentials by NAME only through scripts/agent/env.mjs need(); staff names held in\n// memory for masking only. The run, in order (UTC):\n//   deploys.mjs deploys.json before (10:48) | app-in (10:49) | pos-menu (10:49) | create-event (10:50) |\n//   act reload, open accordion-kitchen-plan, click button-add-first-menu-kids | pick button-till-menu-kids-0|pizza|CF-24|01-p1-kids-line |\n//   act click button-add-menu-extra-kids | pick button-till-menu-kids-1|pepperoni|CF-31 | act click button-add-menu-extra-kids |\n//   act type input-menu-name-kids-2|ZZ TEST fish fingers | pic 02-... | act tab adults | pic 03a-... | act click switch-adults-differ |\n//   act click button-add-menu-extra-adults | pick button-till-menu-adults-3|schnitzel|CF-37|03b-p3-adults-extra | pic 03c-... |\n//   act open accordion-bar-plan | act click button-add-bar-extra | pick button-till-menu-bar-0|juice|CF-63-2|04-p3-bar |\n//   save first (10:53) | act reload ... | pic 05-... | pick kids-0 \"not from the till\" (no pick) 06 | pick bar-0 \"pizza\" (no pick) 07 |\n//   till-read before-package | package (10:54) | till-read after-package | parent-link (10:55) | act reload | rows |\n//   act click button-add-set-menu-item | pick button-till-menu-kids-11|hummus|CF-13 | picbox 08-... | save second |\n//   till-read after-set-menu | pdf (picture 09 rendered locally with PyMuPDF) | settings list | settings dialog (10:59) |\n//   pick kids-10 \"fries\" (no pick) 12 | dead-code (11:00) | pic 13-... | till-read dead-code | clear button-till-menu-kids-11 |\n//   save after-clear | role MANAGER | role RECEPTION (11:02) | timing | cleanup (11:02:44) | GET /STOP (signs every session\n//   out, closes the browser) | deploys.mjs deploys.json after | receipt.mjs | namecheck.mjs receipt.json.\n// Pictures removed after the run as duplicates of others: the unfiltered lists of 03b, 06, 07 and 12, and 15 (the\n// reception account showed the same screen as picture 14). dbg.mjs, dbg2.mjs and look.mjs were operator aids.\nimport { mkdirSync, writeFileSync } from 'node:fs';\nimport { dirname, resolve } from 'node:path';\n`;\nconst body = `const FILES = ${JSON.stringify(files, null, 1)};\nconst dir = process.argv[2];\nif (!dir) { console.log(Object.keys(FILES).join('\\\\n')); process.exit(0); }\nfor (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }\nconsole.log('written', Object.keys(FILES).length, 'files to', dir);\n`;\nwriteFileSync(OUT, head + body);\nconsole.log('proof.mjs', Object.keys(files).length, 'files');\n",
 "steps/act.mjs": "// Small UI actions on the BEO sheet, one per call. arg = \"<action>|<a>|<b>\"\n//   click|<testId>            click an element by test id\n//   type|<testId>|<words>     click an EditableText by test id, type, leave the field (Tab)\n//   tab|kids|adults           the kitchen plan's menu tab\n//   open|<accordion tid>      open a section\n//   reload                    reload the BEO (the board with ?beo=)\n//   row|<testId>              the row's text and the title of its code chip\nimport { openBeo, openSection } from './applib.mjs';\nexport default async (S, arg) => {\n  const [action, a = '', b = ''] = arg.split('|');\n  const page = S.ctxs.app.page;\n  if (action === 'reload') { await openBeo(S, { reload: true }); return { reloaded: true }; }\n  if (action === 'open') { await openSection(page, a); return { opened: a }; }\n  if (action === 'tab') { await page.getByTestId(`button-menu-tab-${a}`).click(); await page.waitForTimeout(400); return { tab: a }; }\n  if (action === 'click') { const l = page.getByTestId(a).first(); await l.scrollIntoViewIfNeeded(); await l.click(); await page.waitForTimeout(500); return { clicked: a }; }\n  if (action === 'type') {\n    const l = page.getByTestId(a).first();\n    await l.scrollIntoViewIfNeeded();\n    await l.click();\n    await page.waitForTimeout(200);\n    const input = page.locator(`[data-testid=\"${a}\"] input, input[data-testid=\"${a}\"]`).first();\n    const focused = (await input.count()) ? input : page.locator(':focus');\n    await focused.fill(b);\n    await page.keyboard.press('Tab');\n    await page.waitForTimeout(400);\n    return { typed: b, into: a };\n  }\n  if (action === 'row') {\n    const l = page.getByTestId(a).first();\n    await l.scrollIntoViewIfNeeded().catch(() => {});\n    const text = S.scrub(S.one(await l.innerText().catch(() => '')));\n    const chip = l.locator('span.font-mono').first();\n    return { text, codeTitle: (await chip.count()) ? await chip.getAttribute('title') : null, searchButton: await l.locator('[data-testid^=\"button-till-menu-\"]').count() };\n  }\n  throw new Error('unknown action ' + action);\n};\n",
 "steps/app-in.mjs": "// The staging administrator in the OTO App through the launcher; names of the signed-in person and of the park's\n// people held for masking only; Central Floresta found by name; the set menu templates and birthday packages read\n// (never changed); the app's till-menu door read for the park and for every park.\nexport default async (S) => {\n  if (!S.ctxs.app) {\n    const ctx = await S.newContext({ width: 1440, height: 1000 });\n    ctx.setDefaultTimeout(30000);\n    const si = await S.launcherSignIn(ctx);\n    S.assert.equal(si, 200, 'launcher sign-in ' + si);\n    const h = await S.handTo(ctx, 'oto_app');\n    S.assert.equal(h.status, 200, 'handoff ' + JSON.stringify(h));\n    S.watch(h.page, 'app-admin');\n    S.ctxs.app = { ctx, page: h.page };\n  }\n  const { ctx } = S.ctxs.app;\n  const u = await S.call(ctx, S.APP, 'GET', '/user');\n  S.assert.equal(u.status, 200, '/api/user ' + u.status);\n  for (const v of [u.body?.fullName, u.body?.firstName, u.body?.lastName, u.body?.nickname, u.body?.displayName, u.body?.username, u.body?.name]) {\n    S.addNames(v);\n    if (typeof v === 'string') for (const part of v.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n  }\n  const br = await S.call(ctx, S.APP, 'GET', '/branches');\n  const list = Array.isArray(br.body) ? br.body : [];\n  const cf = list.find((b) => /Central Floresta/.test(b.name));\n  S.assert.ok(cf, 'Central Floresta not found');\n  const em = await S.call(ctx, S.APP, 'GET', `/employees?branchId=${cf.id}`);\n  const people = Array.isArray(em.body) ? em.body : em.body?.employees ?? [];\n  for (const e of people) {\n    S.addNames(e.nickname, e.fullName, e.thaiName);\n    if (typeof e.fullName === 'string') for (const part of e.fullName.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n  }\n  const sm = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n  const menus = Array.isArray(sm.body) ? sm.body : sm.body?.templates ?? [];\n  const pk = await S.call(ctx, S.APP, 'GET', '/beo/birthday-packages');\n  const pkgs = (Array.isArray(pk.body) ? pk.body : pk.body?.packages ?? []);\n  const one = await S.call(ctx, S.APP, 'GET', `/beo/till-menu?parkId=${cf.id}`);\n  const all = await S.call(ctx, S.APP, 'GET', '/beo/till-menu');\n  const park = one.body?.parks?.[0] ?? null;\n  S.st.app = {\n    role: u.body?.role ?? null,\n    centralFloresta: cf.id, centralFlorestaName: cf.name.trim(), coreBranchId: cf.coreBranchId ?? null,\n    parks: list.map((b) => ({ id: b.id, name: b.name, linked: !!b.coreBranchId, archived: !!b.archived })),\n    peopleAtPark: people.length,\n    setMenuTemplates: menus.map((m) => ({ id: m.id, name: m.name, isActive: m.isActive, branchId: m.branchId ?? null, items: (m.items ?? []).map((i) => ({ id: i.id, type: i.type, label: i.label, productCode: i.productCode ?? null, options: i.options ?? null, optionProductCodes: i.optionProductCodes ?? null })) })),\n    packages: pkgs.map((p) => ({ id: p.id, name: p.name, branchId: p.branchId ?? null, isActive: p.isActive, setMenuTemplateId: p.setMenuTemplateId ?? null })),\n    tillMenuDoor: {\n      park: { route: 'GET /api/beo/till-menu?parkId=<Central Floresta>', status: one.status, parkStatus: park?.status ?? null, message: park?.message ?? null, readAt: park?.readAt ?? null, count: park?.items?.length ?? null },\n      all: { route: 'GET /api/beo/till-menu', status: all.status, parks: (all.body?.parks ?? []).map((p) => ({ parkName: p.parkName, status: p.status, count: p.items.length, message: p.message })) },\n    },\n  };\n  S.st.tillMenuItems = park?.items ?? [];\n  S.save();\n  return { ...S.st.app, setMenuTemplates: S.st.app.setMenuTemplates.length, namesHeld: S.NAMES.size };\n};\n",
 "steps/applib.mjs": "// OTO App helpers. The events board behind the BEO sheet carries customers' party names, so it is hidden for every\n// picture (#root made invisible; the sheet, popovers and dialogs are portaled outside it).\nexport async function hideBoard(page) {\n  return page.evaluate(() => {\n    const root = document.getElementById('root');\n    if (!root) return false;\n    root.setAttribute('data-board-hidden', '1');\n    // Opacity, not only visibility: a descendant styled \"visible\" would show through a hidden parent.\n    root.style.visibility = 'hidden';\n    root.style.opacity = '0';\n    return true;\n  });\n}\nexport async function showBoard(page) {\n  await page.evaluate(() => {\n    const root = document.querySelector('[data-board-hidden]');\n    if (root) { root.style.visibility = ''; root.style.opacity = ''; root.removeAttribute('data-board-hidden'); }\n  });\n}\n/** Open the ZZ TEST party's BEO editor (the events board with ?beo=<id>), waiting for its form. */\nexport async function openBeo(S, { reload = true } = {}) {\n  const page = S.ctxs.app.page;\n  if (reload || !(await page.getByTestId('accordion-event-info').isVisible().catch(() => false))) {\n    await page.goto(S.APP + '/studio/events/kanban?beo=' + S.st.event.id, { waitUntil: 'domcontentloaded', timeout: 120000 });\n    await page.getByTestId('accordion-event-info').waitFor({ timeout: 120000 });\n    await page.waitForTimeout(2500);\n  }\n  return page;\n}\n/** Open an accordion section by its trigger's test id (left open when already open). */\nexport async function openSection(page, tid) {\n  const trig = page.getByTestId(tid).first();\n  await trig.waitFor({ state: 'visible', timeout: 60000 });\n  if ((await trig.getAttribute('data-state')) !== 'open') { await trig.click(); await page.waitForTimeout(800); }\n  return trig;\n}\n/** The accordion item around a trigger. */\nexport function sectionOf(page, tid) {\n  return page.getByTestId(tid).first().locator('xpath=ancestor::*[@data-state][not(self::button)][not(self::h3)][1]');\n}\n/** A picture with the board hidden. */\nexport async function appShot(S, name, opts = {}) {\n  const page = S.ctxs.app.page;\n  await hideBoard(page);\n  await page.waitForTimeout(250);\n  try {\n    return await S.shot(page, name, opts);\n  } finally {\n    await showBoard(page);\n  }\n}\n/** The visible text of a locator, scrubbed, on one line. */\nexport async function textOf(S, loc) {\n  return S.scrub(S.one(await loc.innerText().catch(() => '')));\n}\n",
 "steps/cleanup.mjs": "// Clean-up, each read back: the ZZ TEST party deleted through the app's own route (DELETE /api/admin/events/:id;\n// everything on it goes with it by cascade), then read back on the app (the event, its BEO) and on the till (the party);\n// the set menu templates counted against the start; no ZZ TEST event of this run left at Central Floresta.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  const ev = S.st.event;\n  if (!/^ZZ TEST/.test(ev.title)) throw new Error('refusing to delete an event not named ZZ TEST');\n  const del = await S.call(ctx, S.APP, 'DELETE', `/admin/events/${ev.id}`);\n  const appEvent = await S.call(ctx, S.APP, 'GET', `/admin/events/${ev.id}`);\n  const appBeo = await S.call(ctx, S.APP, 'GET', `/events/${ev.id}/beo`);\n  const till = await S.call(S.ctxs.pos.api, S.POS, 'GET', `/parties/${ev.id}?branchId=${S.st.posMenu.platformBranch.id}`);\n  const list = await S.call(ctx, S.APP, 'GET', `/admin/events?range=all&includeArchived=true&branchId=${S.st.app.centralFloresta}`);\n  const left = Array.isArray(list.body) ? list.body.filter((e) => e.id === ev.id || /ZZ TEST 905/.test(String(e.title || ''))).map((e) => ({ id: e.id, title: e.title })) : null;\n  const tm = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n  const templatesNow = (Array.isArray(tm.body) ? tm.body : []).map((t) => ({ id: t.id, name: t.name, isActive: t.isActive, updatedAt: t.updatedAt ?? null, items: JSON.stringify(t.items) }));\n  S.st.cleanup = {\n    at: new Date().toISOString(),\n    party: { id: ev.id, title: ev.title, delete: { route: 'DELETE /api/admin/events/:id', status: del.status, error: del.status < 300 ? null : del.body } },\n    readBack: {\n      appEvent: { route: 'GET /api/admin/events/:id', status: appEvent.status },\n      appBeo: { route: 'GET /api/events/:id/beo', status: appBeo.status },\n      tillParty: { route: 'GET /api/parties/:id?branchId=<Central Floresta> (till)', status: till.status, code: till.body?.error?.code ?? null },\n      zzTest905AtCentralFloresta: left,\n    },\n    setMenuTemplates: { count: templatesNow.length, unchangedSinceStart: JSON.stringify(templatesNow) === JSON.stringify(S.st.settings?.before ?? []) },\n  };\n  S.save();\n  return S.st.cleanup;\n};\n",
 "steps/clear.mjs": "// \"Not from the till\" on a line's picker: the code taken off, the name kept. arg = \"<search button test id>\"\nexport default async (S, arg) => {\n  const page = S.ctxs.app.page;\n  const btn = page.getByTestId(arg);\n  await btn.evaluate((el) => el.scrollIntoView({ block: 'center' }));\n  await btn.click();\n  await page.getByTestId(`${arg}-search`).fill('not from');\n  await page.waitForTimeout(400);\n  await page.getByTestId(`${arg}-clear`).click();\n  await page.waitForTimeout(500);\n  return { cleared: arg };\n};\n",
 "steps/create-event.mjs": "// A plain ZZ TEST birthday party at Central Floresta on a future weekday, through the app's own route\n// (POST /api/admin/events). Nothing is printed: the party's day is not today and the park names no party slips station.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  if (S.st.event?.id) return { already: S.st.event };\n  const title = 'ZZ TEST 905 till menu';\n  const body = { eventType: 'birthday', title, branchId: S.st.app.centralFloresta, eventDate: '2026-11-25', startTime: '14:00', endTime: '16:00', durationMinutes: 120, numChildren: 8, numAdults: 4, childName: 'ZZ Test Child', status: 'upcoming' };\n  const r = await S.call(ctx, S.APP, 'POST', '/admin/events', body);\n  if (r.status !== 201) throw new Error('create ' + r.status + ' ' + JSON.stringify(r.body).slice(0, 300));\n  S.st.event = { id: r.body.id, title: r.body.title, date: r.body.eventDate, startTime: r.body.startTime, route: 'POST /api/admin/events', status: r.status, createdAt: new Date().toISOString() };\n  S.save();\n  return S.st.event;\n};\n",
 "steps/dbg.mjs": "// Debug: where the board lives and where the sheet is portaled.\nexport default async (S) => {\n  const page = S.ctxs.app.page;\n  return page.evaluate(() => {\n    const root = document.getElementById('root');\n    const dlg = document.querySelector('[role=dialog]');\n    return {\n      root: !!root, rootVis: root ? getComputedStyle(root).visibility : null, rootChildren: root ? root.children.length : null,\n      bodyChildren: [...document.body.children].map((c) => `${c.tagName}#${c.id}.${String(c.className).slice(0, 40)} vis=${getComputedStyle(c).visibility}`),\n      dialogInRoot: dlg ? !!root?.contains(dlg) : null,\n      dialogRect: dlg ? dlg.getBoundingClientRect().toJSON() : null,\n    };\n  });\n};\n",
 "steps/dbg2.mjs": "// Debug: elements whose whole text is two capital letters (an avatar's initials), with a selector path.\nexport default async (S) => {\n  const page = S.ctxs.app.page;\n  return page.evaluate(() => {\n    const out = [];\n    for (const el of document.querySelectorAll('body *')) {\n      if (el.children.length) continue;\n      const t = (el.textContent || '').trim();\n      if (/^[A-Z]{1,3}$/.test(t)) {\n        const r = el.getBoundingClientRect();\n        if (r.width < 1) continue;\n        out.push({ tag: el.tagName, cls: String(el.className).slice(0, 80), parentCls: String(el.parentElement?.className ?? '').slice(0, 80), rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)], len: t.length });\n      }\n    }\n    return out;\n  });\n};\n",
 "steps/dead-code.mjs": "// A code the till does not have, on the ZZ TEST BEO only: the hand-typed \"ZZ TEST fish fingers\" kids line given\n// the made-up code ZZ-DEAD-1 through the app's own kitchen plan route (PUT /api/events/:id/beo/kitchen-plan, the\n// rest of the plan sent back as read), so the BEO shows its \"No longer on the till\" mark. arg = \"set\"\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  const r = await S.call(ctx, S.APP, 'GET', `/events/${S.st.event.id}/beo`);\n  const kp = r.body.kitchenPlan;\n  const menus = JSON.parse(JSON.stringify(kp.menus));\n  const line = menus.kids.find((l) => l.itemName === 'ZZ TEST fish fingers');\n  S.assert.ok(line, 'the ZZ TEST hand-typed line');\n  line.productCode = 'ZZ-DEAD-1';\n  const put = await S.call(ctx, S.APP, 'PUT', `/events/${S.st.event.id}/beo/kitchen-plan`, { menus });\n  const back = await S.call(ctx, S.APP, 'GET', `/events/${S.st.event.id}/beo`);\n  const now = back.body.kitchenPlan.menus.kids.find((l) => l.itemName === 'ZZ TEST fish fingers');\n  S.st.deadCode = { at: new Date().toISOString(), route: 'PUT /api/events/:id/beo/kitchen-plan', status: put.status, lineNow: { itemName: now?.itemName, productCode: now?.productCode ?? null }, kidsLines: back.body.kitchenPlan.menus.kids.length, setMenuLinesKept: back.body.kitchenPlan.menus.kids.filter((l) => l.source === 'set_menu').length };\n  S.save();\n  return S.st.deadCode;\n};\n",
 "steps/look.mjs": "// A look at the page for the driver's operator: a scratch picture (never in the proof folder) and the sheet's text.\n// arg = \"<name>|<reload?>|<section tid,...>\"\nimport { openBeo, openSection, hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [name = 'look', reload = '', sections = ''] = arg.split('|');\n  const page = reload === 'beo' ? await openBeo(S, { reload: true }) : S.ctxs.app.page;\n  for (const tid of sections.split(',').filter(Boolean)) await openSection(page, tid);\n  await hideBoard(page);\n  await S.redact(page);\n  await page.screenshot({ path: S.HERE + 'raw/' + name + '.png', fullPage: false });\n  await showBoard(page);\n  const dlg = page.locator('[role=dialog]').first();\n  const text = S.scrub(S.one(await (await dlg.count() ? dlg : page.locator('body')).innerText().catch(() => ''))).slice(0, 4000);\n  return { url: page.url().replace(/[?#].*/, ''), text };\n};\n",
 "steps/package.mjs": "// The park's own birthday package applied to the ZZ TEST party (POST /api/beo/events/:id/package-snapshot, the\n// route the BEO's package picker calls), so the till's api publishes its plan. Its set menu template becomes the\n// party's (the template itself is only read). Nothing prints: the party is on 25 November and the park names no\n// party slips station.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  const pkg = S.st.app.packages.find((p) => p.name === 'Birthday package, Central Floresta' && p.isActive);\n  S.assert.ok(pkg, 'the Central Floresta package');\n  S.assert.equal(S.st.posMenu.platformBranch.partySlipsStationId, null, 'the park names no party slips station');\n  const r = await S.call(ctx, S.APP, 'POST', `/beo/events/${S.st.event.id}/package-snapshot`, { templateId: pkg.id });\n  S.st.packageApplied = { at: new Date().toISOString(), route: 'POST /api/beo/events/:id/package-snapshot', status: r.status, package: pkg.name, setMenuTemplateId: r.body?.setMenuTemplateId ?? null, slipsTime: r.body?.slipsTime ?? null };\n  S.save();\n  return S.st.packageApplied;\n};\n",
 "steps/parent-link.mjs": "// The set menu's parent link from the BEO (Get Parent Link, POST /api/beo/set-menu-selections), then the parent's\n// choices submitted through the link's own public routes (GET and POST /api/beo/set-menu-selections/public/:token),\n// as the parent's page does: the first option of every choice group. The token is held in memory only, never kept\n// or printed. The ZZ TEST party has no inbox conversation, so no family is told anything.\nimport { openBeo, openSection, hideBoard, showBoard } from './applib.mjs';\nexport default async (S) => {\n  const page = await openBeo(S, { reload: true });\n  await openSection(page, 'accordion-kitchen-plan');\n  await page.getByTestId('button-menu-tab-kids').click();\n  const btn = page.getByTestId('button-get-parent-link');\n  await btn.scrollIntoViewIfNeeded();\n  const resp = page.waitForResponse((r) => new URL(r.url()).pathname === '/api/beo/set-menu-selections' && r.request().method() === 'POST', { timeout: 60000 });\n  await btn.click();\n  const r = await resp;\n  const body = await r.json().catch(() => null);\n  const token = body?.token ?? null;\n  S.assert.ok(token, 'a parent link token');\n  await page.waitForTimeout(1200);\n  const dialogText = S.scrub(S.one(await page.locator('[role=dialog]').last().innerText().catch(() => ''))).replace(/[0-9a-f]{48}/g, '<token>').slice(0, 400);\n  await page.keyboard.press('Escape');\n  await page.waitForTimeout(500);\n  const pub = await S.call(page.context(), S.APP, 'GET', `/beo/set-menu-selections/public/${token}`);\n  const groups = (pub.body?.template?.items ?? []).filter((i) => i.type === 'choice_group');\n  const selections = groups.map((g) => ({ groupId: g.id, chosenOptions: [g.options[0]] }));\n  const sub = await S.call(page.context(), S.APP, 'POST', `/beo/set-menu-selections/public/${token}/submit`, { selections });\n  S.st.parentLink = {\n    at: new Date().toISOString(),\n    getLink: { route: 'POST /api/beo/set-menu-selections (Get Parent Link)', status: r.status(), dialog: dialogText },\n    publicRead: { route: 'GET /api/beo/set-menu-selections/public/<token>', status: pub.status, template: pub.body?.template?.name ?? null },\n    submitted: { route: 'POST /api/beo/set-menu-selections/public/<token>/submit', status: sub.status, choices: groups.map((g) => ({ group: g.label, chosen: g.options[0], code: g.optionProductCodes?.[g.options[0]] ?? g.productCode ?? null })), error: sub.status === 200 ? null : sub.body },\n  };\n  S.save();\n  return S.st.parentLink;\n};\n",
 "steps/pdf.mjs": "// The ZZ TEST BEO's PDF (GET /api/events/:id/beo/pdf, the editor's Download PDF; read only, nothing printed),\n// kept in the scratch folder only; whether any held name appears in its text is checked by the caller's script.\nimport { writeFileSync } from 'node:fs';\nexport default async (S) => {\n  const r = await S.ctxs.app.ctx.request.get(`${S.APP}/api/events/${S.st.event.id}/beo/pdf`, { timeout: 120000 });\n  const buf = await r.body();\n  const file = S.HERE + 'raw/beo.pdf';\n  writeFileSync(file, buf);\n  writeFileSync(S.HERE + 'raw/names.txt', [...S.NAMES].join('\\n'));\n  S.st.pdf = { route: 'GET /api/events/:id/beo/pdf', status: r.status(), type: r.headers()['content-type'] ?? null, bytes: buf.length };\n  S.save();\n  return S.st.pdf;\n};\n",
 "steps/pic.mjs": "// A picture of the BEO sheet with an element scrolled to a place first. arg = \"<file>|<testId to scroll to>|<block>|<shows>\"\nimport { hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [file, tid = '', block = 'center', shows = ''] = arg.split('|');\n  const page = S.ctxs.app.page;\n  if (tid) {\n    const l = page.getByTestId(tid).first();\n    await l.scrollIntoViewIfNeeded();\n    await l.evaluate((el, block) => el.scrollIntoView({ block }), block);\n    await page.waitForTimeout(400);\n  }\n  const sheet = page.locator('[role=dialog]').first();\n  await hideBoard(page);\n  try {\n    return await S.shot(page, file, { element: (await sheet.count()) ? sheet : undefined, shows });\n  } finally {\n    await showBoard(page);\n  }\n};\n",
 "steps/picbox.mjs": "// A picture of one element (by CSS selector) on a taller viewport, board hidden. arg = \"<file>|<css>|<height>|<shows>\"\nimport { hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [file, css, height = '1600', shows = ''] = arg.split('|');\n  const page = S.ctxs.app.page;\n  const old = page.viewportSize();\n  await page.setViewportSize({ width: old.width, height: Number(height) });\n  await page.waitForTimeout(600);\n  const el = page.locator(css).first();\n  await el.evaluate((e) => e.scrollIntoView({ block: 'start' }));\n  await page.waitForTimeout(400);\n  await hideBoard(page);\n  try {\n    return await S.shot(page, file, { element: el, shows });\n  } finally {\n    await showBoard(page);\n    await page.setViewportSize(old);\n  }\n};\n",
 "steps/pick.mjs": "// The picker beside a line: open it, read what it lists (unfiltered), search, pick. Pictures of the sheet.\n// arg = \"<testId of the search button>|<search words>|<code to pick or ->|<picture prefix or ->|<record key>\"\nimport { hideBoard, showBoard } from './applib.mjs';\n\n/** What the open picker lists: groups in order with their item counts, and every option's code. */\nexport async function listed(page, tid) {\n  return page.evaluate((tid) => {\n    const box = document.querySelector('[data-radix-popper-content-wrapper]');\n    if (!box) return null;\n    const groups = [...box.querySelectorAll('[cmdk-group]')].filter((g) => !g.hidden && g.getAttribute('aria-hidden') !== 'true' && getComputedStyle(g).display !== 'none');\n    const opts = [...box.querySelectorAll(`[data-testid^=\"${tid}-option-\"]`)].filter((o) => getComputedStyle(o).display !== 'none' && !o.hidden && o.getAttribute('aria-hidden') !== 'true');\n    return {\n      groups: groups.map((g) => ({ heading: g.querySelector('[cmdk-group-heading]')?.textContent ?? null, items: [...g.querySelectorAll(`[data-testid^=\"${tid}-option-\"]`)].filter((o) => getComputedStyle(o).display !== 'none' && !o.hidden).length })).filter((g) => g.items > 0),\n      options: opts.map((o) => ({ code: o.getAttribute('data-testid').slice(`${tid}-option-`.length), text: (o.textContent ?? '').trim() })),\n      empty: box.querySelector('[cmdk-empty]')?.textContent ?? null,\n      note: box.querySelector(`[data-testid=\"${tid}-unavailable\"]`)?.textContent ?? null,\n      clear: !!box.querySelector(`[data-testid=\"${tid}-clear\"]`),\n    };\n  }, tid);\n}\n\nexport default async (S, arg) => {\n  const [tid, words = '', code = '-', pic = '-', key = tid] = arg.split('|');\n  const page = S.ctxs.app.page;\n  const sheet = page.locator('[role=dialog]').first();\n  const btn = page.getByTestId(tid);\n  await btn.scrollIntoViewIfNeeded();\n  await btn.evaluate((el) => el.scrollIntoView({ block: 'center' }));\n  await page.waitForTimeout(300);\n  const t0 = Date.now();\n  await btn.click();\n  await page.locator('[data-radix-popper-content-wrapper]').waitFor({ timeout: 30000 });\n  // The till's menu loads when the section opens; wait for the list (or the reason there is none).\n  await page.waitForFunction((tid) => !!document.querySelector(`[data-testid=\"${tid}-search\"]`) || /could not|not linked|cannot|not available/.test(document.querySelector(`[data-testid=\"${tid}-unavailable\"]`)?.textContent ?? ''), tid, { timeout: 60000 }).catch(() => {});\n  const openMs = Date.now() - t0;\n  const rec = { at: new Date().toISOString(), tid, openMs, title: await btn.getAttribute('title') };\n  rec.unfiltered = await listed(page, tid);\n  rec.unfilteredCount = rec.unfiltered?.options.length ?? null;\n  rec.firstGroups = rec.unfiltered?.groups.slice(0, 4) ?? null;\n  if (pic !== '-') {\n    await hideBoard(page);\n    rec.pictureList = await S.shot(page, `${pic}a-list.png`, { element: sheet, shows: `${tid}: the picker open, the till's menu unfiltered` });\n    await showBoard(page);\n  }\n  if (words) {\n    await page.getByTestId(`${tid}-search`).fill(words);\n    await page.waitForTimeout(600);\n    rec.search = words;\n    rec.filtered = await listed(page, tid);\n    if (pic !== '-') {\n      await hideBoard(page);\n      rec.pictureSearch = await S.shot(page, `${pic}b-search.png`, { element: sheet, shows: `${tid}: \"${words}\" typed in the picker` });\n      await showBoard(page);\n    }\n  }\n  if (code !== '-') {\n    const opt = page.getByTestId(`${tid}-option-${code}`);\n    rec.pickedText = (await opt.innerText()).replace(/\\s+/g, ' ').trim();\n    await opt.click();\n    await page.waitForTimeout(500);\n    rec.closedAfterPick = !(await page.locator('[data-radix-popper-content-wrapper]').isVisible().catch(() => false));\n    rec.picked = code;\n  } else {\n    await page.keyboard.press('Escape');\n    await page.waitForTimeout(300);\n  }\n  ((S.st.picks ??= {})[key] ??= []).push(rec);\n  S.save();\n  return { ...rec, unfiltered: rec.unfiltered ? { groups: rec.unfiltered.groups, count: rec.unfiltered.options.length, note: rec.unfiltered.note } : null, filtered: rec.filtered ? { options: rec.filtered.options, groups: rec.filtered.groups, empty: rec.filtered.empty } : null };\n};\n",
 "steps/pos-menu.mjs": "// The till's own menu at Central Floresta, read through the platform's admin api on the till's origin (GET\n// /api/branches/:id/menu?includeBeoOnly=true), against what the BEO's picker is given (the app's door). Read only.\nexport default async (S) => {\n  if (!S.ctxs.pos) {\n    const api = await S.request.newContext({ baseURL: S.POS });\n    const r = await api.post('/api/auth/sign-in', { data: { phone: S.need('STAGING_ADMIN_PHONE'), password: S.need('STAGING_ADMIN_PASSWORD') } });\n    S.assert.equal(r.status(), 200, 'POS admin sign-in ' + r.status());\n    S.ctxs.pos = { api };\n  }\n  const { api } = S.ctxs.pos;\n  const branches = await S.call(api, S.POS, 'GET', '/branches');\n  const b = (branches.body?.branches ?? []).find((x) => x.id === S.st.app.coreBranchId);\n  S.assert.ok(b, 'the platform branch the app links Central Floresta to');\n  const menuAll = await S.call(api, S.POS, 'GET', `/branches/${b.id}/menu?includeBeoOnly=true`);\n  const menuTill = await S.call(api, S.POS, 'GET', `/branches/${b.id}/menu`);\n  S.assert.equal(menuAll.status, 200);\n  const products = menuAll.body.products;\n  const cats = new Map(menuAll.body.categories.map((c) => [c.id, c]));\n  const scoped = products.filter((p) => !p.branchId || p.branchId === b.id);\n  const isFood = (p) => p.kind === 'menu' && (p.effectivePrepStation === 'kitchen' || p.effectivePrepStation === 'bar');\n  const live = (p) => p.active && !p.archivedAt;\n  const expected = scoped.filter((p) => isFood(p) && live(p) && p.code && p.code.trim());\n  const door = S.st.tillMenuItems;\n  const doorCodes = new Set(door.map((i) => i.code));\n  const expCodes = new Set(expected.map((p) => p.code.trim()));\n  const missing = expected.filter((p) => !doorCodes.has(p.code.trim())).map((p) => ({ code: p.code, name: p.name }));\n  const extra = door.filter((i) => !expCodes.has(i.code)).map((i) => ({ code: i.code, name: i.name }));\n  const mismatched = [];\n  for (const i of door) {\n    const p = expected.find((x) => x.code.trim() === i.code);\n    if (!p) continue;\n    const diffs = [];\n    if (p.name !== i.name) diffs.push(`name till \"${p.name}\" door \"${i.name}\"`);\n    if (p.priceSatang !== i.priceSatang) diffs.push(`price till ${p.priceSatang} door ${i.priceSatang}`);\n    if ((p.effectiveWeekendSatang ?? p.priceSatang) !== i.priceWeekendSatang) diffs.push(`weekend till ${p.effectiveWeekendSatang} door ${i.priceWeekendSatang}`);\n    if (p.effectivePrepStation !== i.station) diffs.push(`station till ${p.effectivePrepStation} door ${i.station}`);\n    if (!!p.beoOnly !== i.beoOnly) diffs.push('beoOnly');\n    const own = p.categoryId ? cats.get(p.categoryId) : null;\n    if ((own?.name ?? null) !== i.category) diffs.push(`category till ${own?.name} door ${i.category}`);\n    if (diffs.length) mismatched.push({ code: i.code, diffs });\n  }\n  // What the till sells at the kitchen or the bar that the picker can never offer, and why.\n  const sellable = scoped.filter((p) => p.kind === 'menu' && live(p) && !p.beoOnly);\n  const uncodedFood = sellable.filter((p) => isFood(p) && !(p.code && p.code.trim())).map((p) => ({ name: p.name, station: p.effectivePrepStation, category: cats.get(p.categoryId)?.name ?? null }));\n  const noStation = sellable.filter((p) => !isFood(p)).map((p) => ({ name: p.name, code: p.code, station: p.effectivePrepStation }));\n  const offSale = scoped.filter((p) => p.kind === 'menu' && !p.active && !p.archivedAt && p.code).map((p) => ({ code: p.code, name: p.name }));\n  const codes = expected.map((p) => p.code.trim());\n  const dupCodes = codes.filter((c, i) => codes.indexOf(c) !== i);\n  const tillSells = (menuTill.body?.products ?? []).filter((p) => (!p.branchId || p.branchId === b.id) && p.kind === 'menu' && live(p));\n  const sample = ['Margherita', 'Pizza', 'Juice', 'Coke', 'Calamari', 'Hummus', 'French'].map((w) => ({ word: w, till: expected.filter((p) => p.name.toLowerCase().includes(w.toLowerCase())).map((p) => `${p.code} ${p.name}`), door: door.filter((i) => i.name.toLowerCase().includes(w.toLowerCase())).map((i) => `${i.code} ${i.name}`) }));\n  S.st.posMenu = {\n    platformBranch: { id: b.id, name: b.name, partySlipsStationId: b.partySlipsStationId ?? null },\n    routes: { withBeoOnly: `GET /api/branches/:id/menu?includeBeoOnly=true ${menuAll.status}`, tillSelling: `GET /api/branches/:id/menu ${menuTill.status}` },\n    products: { total: products.length, atThisBranchOrOperatorWide: scoped.length },\n    expected: expected.length, door: door.length,\n    doorByStation: { kitchen: door.filter((i) => i.station === 'kitchen').length, bar: door.filter((i) => i.station === 'bar').length, beoOnly: door.filter((i) => i.beoOnly).length },\n    missingFromDoor: missing, extraInDoor: extra, mismatched, duplicateCodes: dupCodes,\n    sameOrder: JSON.stringify(door.map((i) => i.code)) === JSON.stringify(door.map((i) => i.code)),\n    tillSellingGridMenuItems: tillSells.length,\n    uncodedKitchenBarItemsOnSale: uncodedFood,\n    menuItemsPrintingNowhereOnSale: noStation,\n    offSaleCodedItems: offSale,\n    sample,\n  };\n  S.save();\n  return { ...S.st.posMenu, uncodedKitchenBarItemsOnSale: uncodedFood.length, uncodedSample: uncodedFood.slice(0, 15), menuItemsPrintingNowhereOnSale: noStation.length, noStationSample: noStation.slice(0, 10) };\n};\n",
 "steps/role.mjs": "// Who sees the search: an existing staging account (manager or reception; none created) through the launcher into\n// the OTO App; its role, the till-menu door's answer, and what the ZZ TEST BEO shows it. Signed out after, read back.\n// arg = \"<MANAGER|RECEPTION>|<picture file or ->\"\nimport { hideBoard, showBoard } from './applib.mjs';\nexport default async (S, arg) => {\n  const [who, pic = '-'] = arg.split('|');\n  const ctx = await S.newContext({ width: 1440, height: 1000 });\n  ctx.setDefaultTimeout(30000);\n  const rec = { who: who.toLowerCase(), at: new Date().toISOString() };\n  try {\n    rec.launcherSignIn = await S.launcherSignIn(ctx, `STAGING_${who}_PHONE`, `STAGING_${who}_PASSWORD`);\n    if (rec.launcherSignIn !== 200) return rec;\n    const h = await S.handTo(ctx, 'oto_app');\n    rec.handoff = { status: h.status, exchange: h.exchange ?? null, code: h.code ?? null, message: h.message ? S.scrub(h.message) : null };\n    if (h.status !== 200) return rec;\n    const page = h.page;\n    S.watch(page, 'app-' + rec.who);\n    const u = await S.call(ctx, S.APP, 'GET', '/user');\n    rec.appUser = u.status;\n    rec.role = u.body?.role ?? null;\n    for (const v of [u.body?.fullName, u.body?.firstName, u.body?.lastName, u.body?.nickname, u.body?.displayName, u.body?.username, u.body?.name]) {\n      S.addNames(v);\n      if (typeof v === 'string') for (const part of v.trim().split(/\\s+/)) if (part.length >= 3) S.addNames(part);\n    }\n    const door = await S.call(ctx, S.APP, 'GET', `/beo/till-menu?parkId=${S.st.app.centralFloresta}`);\n    rec.tillMenuDoor = { route: 'GET /api/beo/till-menu?parkId=<Central Floresta>', status: door.status, parkStatus: door.body?.parks?.[0]?.status ?? null, count: door.body?.parks?.[0]?.items?.length ?? null, message: door.status >= 400 ? S.scrub(JSON.stringify(door.body)).slice(0, 160) : null };\n    const beo = await S.call(ctx, S.APP, 'GET', `/events/${S.st.event.id}/beo`);\n    rec.beoRead = beo.status;\n    await page.goto(S.APP + '/studio/events/kanban?beo=' + S.st.event.id, { waitUntil: 'domcontentloaded', timeout: 120000 });\n    await page.waitForTimeout(6000);\n    rec.landedPath = new URL(page.url()).pathname;\n    const editor = await page.getByTestId('accordion-kitchen-plan').isVisible().catch(() => false);\n    rec.beoEditorOpen = editor;\n    if (editor) {\n      const trig = page.getByTestId('accordion-kitchen-plan');\n      if ((await trig.getAttribute('data-state')) !== 'open') { await trig.click(); await page.waitForTimeout(1500); }\n      rec.searchButtons = await page.locator('[data-testid^=\"button-till-menu-\"]').count();\n      const first = page.locator('[data-testid^=\"button-till-menu-\"]').first();\n      if (rec.searchButtons) {\n        await first.evaluate((el) => el.scrollIntoView({ block: 'center' }));\n        await first.click();\n        await page.waitForTimeout(2000);\n        rec.pickerSays = S.scrub(S.one(await page.locator('[data-radix-popper-content-wrapper]').innerText().catch(() => ''))).slice(0, 200);\n        rec.pickerOptions = await page.locator('[data-radix-popper-content-wrapper] [data-testid*=\"-option-\"]').count();\n      }\n    } else {\n      rec.screenSays = S.scrub(S.one(await page.locator('body').innerText().catch(() => ''))).slice(0, 300);\n    }\n    if (pic !== '-') {\n      await hideBoard(page);\n      const sheet = page.locator('[role=dialog]').first();\n      const avatar = [page.locator('span.rounded-full.bg-primary')];\n      if (editor) rec.picture = await S.shot(page, pic, { element: sheet, mask: avatar, shows: `${rec.who} (${rec.role}): the ZZ TEST BEO` });\n      else { await showBoard(page); rec.picture = await S.shot(page, pic, { mask: avatar, shows: `${rec.who} (${rec.role}): the BEO address` }); }\n      await showBoard(page);\n    }\n    return rec;\n  } finally {\n    const out = {};\n    out.appLogout = (await S.call(ctx, S.APP, 'POST', '/logout', {}).catch(() => ({ status: 'error' }))).status;\n    out.launcherSignOut = (await S.call(ctx, S.LAUNCHER, 'POST', '/auth/sign-out', {}).catch(() => ({ status: 'error' }))).status;\n    out.appUserAfter = (await S.call(ctx, S.APP, 'GET', '/user').catch(() => ({ status: 'error' }))).status;\n    out.launcherMeAfter = (await S.call(ctx, S.LAUNCHER, 'GET', '/me').catch(() => ({ status: 'error' }))).status;\n    rec.signOut = out;\n    await ctx.close().catch(() => {});\n    (S.st.roles ??= {})[rec.who] = rec;\n    S.save();\n  }\n};\n",
 "steps/rows.mjs": "// Every kitchen line row on screen: its test id, its text, whether it has the till search, its code chip and its\n// \"No longer on the till\" mark; split by the set menu block (\"Resolved Items\" / \"Manual Override\") and the rest.\nexport default async (S) => {\n  const page = S.ctxs.app.page;\n  const rows = await page.evaluate(() => {\n    const out = [];\n    for (const r of document.querySelectorAll('[data-testid^=\"menu-item-\"], [data-testid^=\"bar-item-\"]')) {\n      const id = r.getAttribute('data-testid');\n      if (!/^(menu-item-(kids|adults)-\\d+|bar-item-\\d+)$/.test(id)) continue;\n      const inSetBlock = !!r.closest('.border-emerald-500\\\\/40');\n      out.push({\n        id, inSetBlock,\n        text: (r.innerText || '').replace(/\\s+/g, ' ').trim(),\n        search: !!r.querySelector('[data-testid^=\"button-till-menu-\"]'),\n        code: r.querySelector('span.font-mono')?.textContent ?? null,\n        codeTitle: r.querySelector('span.font-mono')?.getAttribute('title') ?? null,\n        dead: r.querySelector('[data-testid*=\"code-dead\"]')?.textContent ?? null,\n      });\n    }\n    const block = document.querySelector('.border-emerald-500\\\\/40');\n    return { rows: out, setBlock: block ? (block.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 1200) : null };\n  });\n  return { rows: rows.rows.map((r) => ({ ...r, text: S.scrub(r.text) })), setBlock: rows.setBlock ? S.scrub(rows.setBlock) : null };\n};\n",
 "steps/save.mjs": "// Save BEO (the sheet's Save), the writes it sends and their answers, the toasts; then the BEO read back through\n// the app's own route (GET /api/events/:id/beo): the kitchen and bar lines as saved. arg = \"<key>\"\nexport default async (S, arg) => {\n  const key = arg || 'save';\n  const page = S.ctxs.app.page;\n  const writes = [];\n  const on = (r) => {\n    try {\n      const u = new URL(r.url());\n      const m = r.request().method();\n      if (m !== 'GET' && u.pathname.startsWith('/api/')) writes.push({ method: m, path: u.pathname.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/g, ':id'), status: r.status() });\n    } catch {}\n  };\n  page.on('response', on);\n  const t0 = Date.now();\n  const done = page.waitForResponse((r) => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(r.url()).pathname) && r.request().method() === 'PUT', { timeout: 120000 });\n  await page.getByTestId('button-save-beo').click();\n  const resp = await done;\n  await page.waitForTimeout(2500);\n  page.off('response', on);\n  const toasts = (await page.locator('li[role=status]').allInnerTexts().catch(() => [])).map((t) => S.scrub(S.one(t)));\n  const read = await readBeo(S);\n  const rec = { at: new Date().toISOString(), putStatus: resp.status(), ms: Date.now() - t0, writes, toasts, read };\n  (S.st.saves ??= {})[key] = rec;\n  S.save();\n  return rec;\n};\n\nexport async function readBeo(S) {\n  const r = await S.call(S.ctxs.app.ctx, S.APP, 'GET', `/events/${S.st.event.id}/beo`);\n  const kp = r.body?.kitchenPlan ?? null;\n  const bp = r.body?.barPlan ?? null;\n  const line = (l) => ({ itemName: l.itemName, productCode: l.productCode ?? null, quantity: l.quantity, price: l.price ?? null, included: l.included ?? null, source: l.source ?? null, groupId: l.groupId ?? null, notes: l.notes || null });\n  return {\n    route: 'GET /api/events/:id/beo', status: r.status,\n    kitchen: kp ? { setMenuEnabled: kp.setMenuEnabled ?? null, setMenuTemplateId: kp.setMenuTemplateId ?? null, adultsDiffer: kp.menus?.adultsDiffer ?? null, kids: (kp.menus?.kids ?? []).map(line), adults: (kp.menus?.adults ?? []).map(line) } : null,\n    bar: bp ? { items: (bp.items ?? []).map(line) } : null,\n  };\n}\n",
 "steps/settings.mjs": "// Settings > Set menu templates: the list looked at (a template expanded, nothing edited), then a NEW template's\n// dialog (never saved, no name typed, closed with Cancel): a Code box's search, a dead code's mark, a pick.\n// The templates are counted before and after through GET /api/beo/set-menu-templates. arg = \"<phase>\"\n//   list      the list, the dead codes the app would mark (computed from every park's till menu), pictures\n//   dialog    the new-template dialog: Always Included, a dead code typed, a pick; a choice option's pick; Cancel\nexport default async (S, arg) => {\n  const phase = arg || 'list';\n  const page = S.ctxs.app.page;\n  const { ctx } = S.ctxs.app;\n  const templates = async () => {\n    const r = await S.call(ctx, S.APP, 'GET', '/beo/set-menu-templates');\n    return (Array.isArray(r.body) ? r.body : []).map((t) => ({ id: t.id, name: t.name, isActive: t.isActive, updatedAt: t.updatedAt ?? null, items: JSON.stringify(t.items) }));\n  };\n  const rec = (S.st.settings ??= {});\n  if (phase === 'list') {\n    rec.before = await templates();\n    const all = await S.call(ctx, S.APP, 'GET', '/beo/till-menu');\n    const live = new Set((all.body?.parks ?? []).filter((p) => p.status === 'ok').flatMap((p) => p.items.map((i) => i.code)));\n    const dead = [];\n    for (const t of S.st.app.setMenuTemplates) {\n      for (const it of t.items) {\n        if (it.productCode && !live.has(it.productCode.trim())) dead.push({ template: t.name, active: t.isActive, item: it.label, code: it.productCode });\n        for (const [opt, c] of Object.entries(it.optionProductCodes ?? {})) if (c && !live.has(String(c).trim())) dead.push({ template: t.name, active: t.isActive, item: `${it.label} / ${opt}`, code: c });\n      }\n    }\n    rec.deadCodesExpected = dead;\n    await page.goto(S.APP + '/studio/event-settings', { waitUntil: 'domcontentloaded', timeout: 120000 });\n    await page.getByTestId('tab-set-menus').waitFor({ timeout: 120000 });\n    await page.getByTestId('tab-set-menus').click();\n    await page.getByTestId('button-add-set-menu-template').waitFor({ timeout: 60000 });\n    await page.waitForTimeout(2500);\n    const floresta = S.st.app.setMenuTemplates.find((t) => t.id === '0b1db99d-296a-4418-abb8-9d6071a367c4');\n    await page.getByTestId(`toggle-template-${floresta.id}`).click();\n    await page.waitForTimeout(800);\n    const deadTemplates = [...new Set(dead.map((d) => d.template))];\n    for (const name of deadTemplates) {\n      const t = S.st.app.setMenuTemplates.find((x) => x.name === name);\n      if (t && t.id !== floresta.id) { await page.getByTestId(`toggle-template-${t.id}`).click().catch(() => {}); await page.waitForTimeout(500); }\n    }\n    rec.marksOnScreen = await page.evaluate(() => [...document.querySelectorAll('[data-testid^=\"text-set-menu-view-\"]')].map((e) => e.textContent));\n    rec.searchButtonsInList = await page.locator('[data-testid^=\"button-set-menu-item-till-\"], [data-testid^=\"button-set-menu-option-till-\"]').count();\n    await page.getByTestId(`set-menu-template-${floresta.id}`).evaluate((e) => e.scrollIntoView({ block: 'start' }));\n    await page.waitForTimeout(400);\n    rec.listPicture = await S.shot(page, '10-p7-settings-set-menu-templates-list-live-codes-no-mark.png', { mask: [page.locator('span.rounded-full.bg-primary')], shows: 'Settings > Set menu templates: the Central Floresta template expanded (looked at only); live codes, no mark; the signed-in initials masked' });\n    if (deadTemplates.length) {\n      const t = S.st.app.setMenuTemplates.find((x) => x.name === deadTemplates[0]);\n      await page.getByTestId(`set-menu-template-${t.id}`).evaluate((e) => e.scrollIntoView({ block: 'start' }));\n      await page.waitForTimeout(400);\n      rec.deadPicture = await S.shot(page, '10b-p7-settings-list-a-real-template-dead-code-marked.png', { mask: [page.locator('span.rounded-full.bg-primary')], shows: `Settings list: a real template (${t.name}) with a code the till no longer has, marked; nothing edited` });\n    }\n    S.save();\n    return { before: rec.before.length, deadCodesExpected: dead, marksOnScreen: rec.marksOnScreen, searchButtonsInList: rec.searchButtonsInList };\n  }\n  if (phase === 'dialog') {\n    const dlg = page.getByRole('dialog', { name: /Set Menu Template/ });\n    const avatar = [page.locator('span.rounded-full.bg-primary')];\n    await page.goto(S.APP + '/studio/event-settings', { waitUntil: 'domcontentloaded', timeout: 120000 });\n    await page.getByTestId('tab-set-menus').click();\n    await page.getByTestId('button-add-set-menu-template').waitFor({ timeout: 60000 });\n    await page.waitForTimeout(1500);\n    rec.beforeDialog = await templates();\n    await page.getByTestId('button-add-set-menu-template').click();\n    await dlg.waitFor({ timeout: 30000 });\n    rec.dialogTitle = S.one(await dlg.locator('h2').first().innerText());\n    await page.getByTestId('button-add-always-included').click();\n    await page.waitForTimeout(400);\n    const codeBox = dlg.locator('[data-testid^=\"input-set-menu-item-code-\"]').first();\n    const itemId = (await codeBox.getAttribute('data-testid')).slice('input-set-menu-item-code-'.length);\n    const btn = `button-set-menu-item-till-${itemId}`;\n    rec.searchBeside = await page.getByTestId(btn).count();\n    await codeBox.fill('ZZ-DEAD-1');\n    await page.waitForTimeout(500);\n    rec.deadMark = await page.getByTestId(`text-set-menu-item-code-dead-${itemId}`).textContent().catch(() => null);\n    rec.deadPicture = await S.shot(page, '11a-p7-new-template-dialog-dead-code-marked.png', { mask: avatar, shows: 'New Set Menu Template (never saved): Always Included item, ZZ-DEAD-1 typed in Code: \"No longer on the till\"; the search beside the Code box' });\n    await page.getByTestId(btn).click();\n    await page.getByTestId(`${btn}-search`).waitFor({ timeout: 30000 });\n    await page.getByTestId(`${btn}-search`).fill('fries');\n    await page.waitForTimeout(500);\n    rec.searchFries = await page.evaluate((btn) => [...document.querySelectorAll(`[data-testid^=\"${btn}-option-\"]`)].map((o) => (o.textContent ?? '').trim()), btn);\n    rec.searchPicture = await S.shot(page, '11b-p7-new-template-code-search-fries.png', { mask: avatar, shows: 'The Code box\\'s search: \"fries\"' });\n    await page.getByTestId(`${btn}-option-CF-11`).click();\n    await page.waitForTimeout(500);\n    rec.afterPick = { code: await codeBox.inputValue(), deadMark: await page.getByTestId(`text-set-menu-item-code-dead-${itemId}`).count(), label: await dlg.locator('input[placeholder^=\"Item name\"]').first().inputValue() };\n    // A choice group with one option: the option's Code box has its own search.\n    await page.getByTestId('button-add-choice-group').click();\n    await page.waitForTimeout(400);\n    const optInput = dlg.locator('input[placeholder=\"Add option, press Enter...\"]').last();\n    await optInput.fill('ZZ option');\n    await optInput.press('Enter');\n    await page.waitForTimeout(400);\n    const optCode = dlg.locator('[data-testid^=\"input-set-menu-option-code-\"]').last();\n    const optTid = (await optCode.getAttribute('data-testid')).replace('input-set-menu-option-code-', 'button-set-menu-option-till-');\n    await page.getByTestId(optTid).click();\n    await page.getByTestId(`${optTid}-search`).fill('margherita');\n    await page.waitForTimeout(400);\n    await page.getByTestId(`${optTid}-option-CF-24`).click();\n    await page.waitForTimeout(400);\n    rec.optionAfterPick = { code: await optCode.inputValue(), groupLabel: await dlg.locator('input[placeholder^=\"Group name\"]').last().inputValue() };\n    rec.pickedPicture = await S.shot(page, '11c-p7-new-template-picked-codes-no-mark.png', { mask: avatar, shows: 'After the picks (never saved): the Always Included item took CF-11 and the name French fries, the mark gone; the choice option took CF-24, the group name left empty' });\n    await dlg.getByRole('button', { name: 'Cancel', exact: true }).click();\n    await page.waitForTimeout(800);\n    rec.dialogClosed = !(await dlg.isVisible().catch(() => false));\n    rec.after = await templates();\n    rec.unchanged = JSON.stringify(rec.after) === JSON.stringify(rec.beforeDialog) && JSON.stringify(rec.after) === JSON.stringify(rec.before);\n    S.save();\n    return { dialogTitle: rec.dialogTitle, searchBeside: rec.searchBeside, deadMark: rec.deadMark, searchFries: rec.searchFries, afterPick: rec.afterPick, optionAfterPick: rec.optionAfterPick, dialogClosed: rec.dialogClosed, before: rec.before.length, after: rec.after.length, unchanged: rec.unchanged };\n  }\n  throw new Error('phase ' + phase);\n};\n",
 "steps/signout.mjs": "// Every session of this run signed out, each read back: the administrator's OTO App and launcher sessions, and the\n// platform admin api session on the till's origin. (The manager and reception sessions were signed out in role.mjs.)\nexport default async (S) => {\n  const safe = (p) => p.catch((e) => ({ status: 'error ' + e.message }));\n  const out = { at: new Date().toISOString() };\n  if (S.ctxs.app) {\n    const { ctx } = S.ctxs.app;\n    out.app = {\n      appLogout: (await safe(S.call(ctx, S.APP, 'POST', '/logout', {}))).status,\n      launcherSignOut: (await safe(S.call(ctx, S.LAUNCHER, 'POST', '/auth/sign-out', {}))).status,\n      appUserAfter: (await safe(S.call(ctx, S.APP, 'GET', '/user'))).status,\n      launcherMeAfter: (await safe(S.call(ctx, S.LAUNCHER, 'GET', '/me'))).status,\n    };\n    await ctx.close().catch(() => {});\n  }\n  if (S.ctxs.pos) {\n    const { api } = S.ctxs.pos;\n    out.pos = {\n      signOut: (await safe(S.call(api, S.POS, 'POST', '/auth/sign-out', {}))).status,\n      meAfter: (await safe(S.call(api, S.POS, 'GET', '/me'))).status,\n    };\n    await api.dispose().catch(() => {});\n  }\n  S.st.signOut = out;\n  S.save();\n  return out;\n};\n",
 "steps/till-read.mjs": "// The ZZ TEST party read back on the till's api (GET /api/parties/:id?branchId=, as SCRUM-861 did): its plan's\n// set menu lines (what the kitchen gets) and bar lines, with their codes. Read only. arg = \"<key>\"\nexport default async (S, arg) => {\n  const key = arg || 'read';\n  const { api } = S.ctxs.pos;\n  const r = await S.call(api, S.POS, 'GET', `/parties/${S.st.event.id}?branchId=${S.st.posMenu.platformBranch.id}`);\n  const plan = r.body?.plan ?? null;\n  const rec = {\n    at: new Date().toISOString(), route: 'GET /api/parties/:id?branchId=<Central Floresta>', status: r.status,\n    error: r.status === 200 ? null : r.body?.error ?? r.body,\n    title: r.body?.event?.title ?? null, planStatus: r.body?.planStatus ?? null,\n    package: plan?.package?.name ?? null,\n    setMenu: plan ? plan.setMenu.map((m) => ({ productCode: m.productCode, name: m.name, qty: m.qty, choiceGroup: m.choiceGroup, chosenOption: m.chosenOption, note: m.note, audience: m.audience ?? null, adultsNote: m.adultsNote ?? null })) : null,\n    barItems: plan ? plan.barItems : null,\n    kitchen: plan?.kitchen ?? null,\n    slips: r.body?.slips ? { station: r.body.slips.station ?? null, records: (r.body.slips.records ?? []).length } : null,\n  };\n  (S.st.tillReads ??= {})[key] = rec;\n  S.save();\n  return rec;\n};\n",
 "steps/timing.mjs": "// How long the app's till-menu door takes: a read, then a second within the minute it holds an answer. Read only.\nexport default async (S) => {\n  const { ctx } = S.ctxs.app;\n  const t = async () => { const t0 = Date.now(); const r = await S.call(ctx, S.APP, 'GET', `/beo/till-menu?parkId=${S.st.app.centralFloresta}`); return { status: r.status, ms: Date.now() - t0, readAt: r.body?.parks?.[0]?.readAt ?? null, count: r.body?.parks?.[0]?.items?.length ?? null }; };\n  const first = await t();\n  const second = await t();\n  const all0 = Date.now(); const all = await S.call(ctx, S.APP, 'GET', '/beo/till-menu'); const allMs = Date.now() - all0;\n  S.st.timing = { at: new Date().toISOString(), first, second, allParks: { status: all.status, ms: allMs } };\n  S.save();\n  return S.st.timing;\n};\n"
};
const dir = process.argv[2];
if (!dir) { console.log(Object.keys(FILES).join('\n')); process.exit(0); }
for (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }
console.log('written', Object.keys(FILES).length, 'files to', dir);
